<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Detail Pengguna — FRExam</title><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;600;700;800&display=swap" rel="stylesheet"><style>:root{font-family:Inter,sans-serif;color:#1f2937}*{box-sizing:border-box}body{margin:0;min-height:100vh;padding:30px 20px;background:linear-gradient(135deg,#f4f7fb,#e8eef7)}body:before{content:"✦";position:fixed;z-index:-1;right:-45px;bottom:-25px;font-size:220px;color:#a0b4d14b}.wrap{max-width:980px;margin:auto}.back{display:inline-block;padding:10px 13px;border-radius:10px;background:#fff9;border:1px solid #fff;color:#23395d;text-decoration:none;font-size:13px;font-weight:800}.profile{position:relative;overflow:hidden;margin-top:18px;padding:28px 30px;border-radius:22px;background:linear-gradient(115deg,#23395d,#365d92);color:#fff}.profile:after{content:"✦";position:absolute;right:25px;top:-50px;color:#ffffff15;font-size:165px}.profile>*{position:relative}.badge{display:inline-block;padding:5px 9px;border-radius:20px;background:#ffffff23;font-size:11px;font-weight:800;text-transform:uppercase}.profile h1{margin:10px 0 7px;font-size:28px}.profile p{margin:5px 0;color:#e7effa}.card{margin-top:18px;padding:22px;background:#fffd;border:1px solid #fff;border-radius:18px;box-shadow:0 14px 30px #23395d12;overflow:auto}.card h2{margin-top:0;color:#23395d;font-size:20px}table{width:100%;border-collapse:collapse;min-width:560px}th,td{text-align:left;padding:12px 8px;border-bottom:1px solid #e4ecf4}th{color:#64748b;font-size:11px;text-transform:uppercase}.empty{color:#64748b}</style></head><body><main class="wrap"><a class="back" href="{{ route('admin.users') }}">← Manajemen Pengguna</a><section class="profile"><span class="badge">{{ $user->role }}</span><h1>{{ $user->name }}</h1><p>Identitas: {{ $user->role==='student'?$user->nisn:($user->role==='teacher'?$user->nip:$user->username) }} · Status {{ $user->is_active?'Aktif':'Nonaktif' }}</p><p>Login terakhir: {{ $user->last_login_at??'Belum pernah login' }}</p></section>@if($user->role==='student')<section class="card"><h2>Riwayat Ujian & Nilai</h2><table><thead><tr><th>Ujian</th><th>Status</th><th>Nilai</th><th>Tanggal</th></tr></thead><tbody>@forelse($attempts as $attempt)<tr><td>{{ $attempt->exam_title }}</td><td>{{ $attempt->status }}</td><td>{{ $attempt->score??'—' }}</td><td>{{ $attempt->submitted_at??$attempt->started_at }}</td></tr>@empty<tr><td class="empty" colspan="4">Belum ada riwayat.</td></tr>@endforelse</tbody></table></section>@elseif($user->role==='teacher')<section class="card"><h2>Ujian yang Dibuat</h2>@forelse($createdExams as $exam)<p><strong>{{ $exam->title }}</strong> · {{ $exam->subject }} · Token: <strong>{{ $exam->token }}</strong></p>@empty<p class="empty">Belum ada ujian yang dibuat.</p>@endforelse</section>@endif</main></body></html>
